def _unescape_pdf_str(bs: bytes) -> str:
    bs = bs[1:-1]  # strip parentheses
    out = bytearray()
    i = 0
    while i < len(bs):
        c = bs[i]
        if c == 0x5C and i + 1 < len(bs):  # backslash
            n = bs[i + 1]
            if n in b"nrtbf":
                out.append(
                    {
                        ord("n"): 10,
                        ord("r"): 13,
                        ord("t"): 9,
                        ord("b"): 8,
                        ord("f"): 12,
                    }[n]
                )
                i += 2
