{"summary": "Create deterministic reflow compliance solver script", "security_risk": "MEDIUM", "command": "create", "path": "/app/solve_reflow.py", "file_text": "#!/usr/bin/env python3

from __future__ import annotations

import json
import math
import re
import zlib
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple

import pandas as pd

DATA_DIR = Path("/app/data")
OUT_DIR = Path("/app/output")


def r2(x: Any) -> Any:
    if x is None:
        return None
    try:
        xf = float(x)
    except Exception:
        return None
    if math.isnan(xf) or math.isinf(xf):
        return None
    return float(round(xf, 2))


def _pdf_decompress_flate_streams(pdf_bytes: bytes) -> List[bytes]:
    starts = [m.end() for m in re.finditer(rb"stream\r?\n", pdf_bytes)]
    out: List[bytes] = []
    for st in starts:
        en = pdf_bytes.find(b"endstream", st)
        if en == -1:
            continue
        raw = pdf_bytes[st:en].rstrip(b"\r\n")
        # Many streams are not Flate; only keep ones we can zlib-decompress.
        data = None
        for wbits in (zlib.MAX_WBITS, -zlib.MAX_WBITS):
            try:
                data = zlib.decompress(raw, wbits)
                break
            except Exception:
                pass
        if data is not None:
            out.append(data)
    return out


_PDF_STR_RE = re.compile(rb"\((?:\\.|[^\\\)])*\)")


def _unescape_pdf_str(bs: bytes) -> str:
    bs = bs[1:-1]  # strip parentheses
    out = bytearray()
    i = 0
    while i < len(bs):
        c = bs[i]
        if c == 0x5C and i + 1 < len(bs):  # backslash
            n = bs[i + 1]
            if n in b"nrtbf":
                out.append(
                    {
                        ord("n"): 10,
                        ord("r"): 13,
                        ord("t"): 9,
                        ord("b"): 8,
                        ord("f"): 12,
                    }[n]
                )
                i += 2
                continue
            if 48 <= n <= 55:  # octal
                j = i + 1
                octs = []
                for _ in range(3):
                    if j < len(bs) and 48 <= bs[j] <= 55:
                        octs.append(bs[j])
                        j += 1
                    else:
                        break
                out.append(int(bytes(octs), 8))
                i = j
                continue
            out.append(n)
            i += 2
            continue
        out.append(c)
        i += 1
    return out.decode("latin1", errors="ignore")


def extract_handbook_text(pdf_path: Path) -> str:
    pdf_bytes = pdf_path.read_bytes()
    streams = _pdf_decompress_flate_streams(pdf_bytes)
    tokens: List[str] = []
    for s in streams:
        for m in _PDF_STR_RE.finditer(s):
            t = _unescape_pdf_str(m.group(0)).strip()
            if t:
                tokens.append(t)
    return " ".join(tokens)


@dataclass(frozen=True)
class HandbookCfg:
    preheat_tmin_c: float
    preheat_tmax_c: float
    ramp_rate_limit_c_per_s: float
    tal_min_s: float
    tal_max_s: float
    peak_margin_c: float


def parse_handbook_cfg(text: str) -> HandbookCfg:
    # Preheat temperature band: "between 100°C to 150°C"
    m = re.search(r"between\s+(\d+)\s*\S*\s*to\s*(\d+)\s*\S*", text, flags=re.I)
    if not m:
        raise RuntimeError("Could not locate preheat temperature band in handbook text")
    preheat_tmin = float(m.group(1))
    preheat_tmax = float(m.group(2))

    # Ramp limit: "less than 2°C/second"
    m = re.search(r"less\s+than\s+(\d+(?:\.\d+)?)\s*\S*\s*/\s*second", text, flags=re.I)
    if not m:
        # Fallback for a common OCR/PDF encoding artifact around the degree symbol.
        m = re.search(r"less\s+than\s+(\d+(?:\.\d+)?)\s*.*?c/second", text, flags=re.I)
    if not m:
        raise RuntimeError("Could not locate ramp-rate limit in handbook text")
    ramp_limit = float(m.group(1))

    # TAL window: "wetting time is normally 30 to 60 seconds"
    m = re.search(
        r"wetting\s+time\s+is\s+normally\s+(\d+)\s+to\s+(\d+)\s+seconds",
        text,
        flags=re.I,
    )
    if not m:
        raise RuntimeError("Could not locate wetting time (TAL) window in handbook text")
    tal_min = float(m.group(1))
    tal_max = float(m.group(2))

    # Peak margin: "must be exceeded by approximately 20°C"
    m = re.search(r"exceeded\s+by\s+approximately\s+(\d+)\s*\S*", text, flags=re.I)
    if not m:
        raise RuntimeError("Could not locate peak margin above liquidus in handbook text")
    peak_margin = float(m.group(1))

    return HandbookCfg(
        preheat_tmin_c=preheat_tmin,
        preheat_tmax_c=preheat_tmax,
        ramp_rate_limit_c_per_s=ramp_limit,
        tal_min_s=tal_min,
        tal_max_s=tal_max,
        peak_margin_c=peak_margin,
    )


def max_slope_in_temp_band(df_tc: pd.DataFrame, tmin: float, tmax: float) -> Optional[float]:
    g = df_tc.sort_values("time_s", kind="mergesort")
    t = g["time_s"].to_numpy(dtype=float)
    y = g["temp_c"].to_numpy(dtype=float)
    best: Optional[float] = None
    for i in range(1, len(g)):
        dt = t[i] - t[i - 1]
        if dt <= 0:
            continue
        if (tmin <= y[i - 1] <= tmax) and (tmin <= y[i] <= tmax):
            s = (y[i] - y[i - 1]) / dt
            best = s if best is None else max(best, s)
    return best


def time_above_threshold_s(df_tc: pd.DataFrame, thr: float) -> float:
    g = df_tc.sort_values("time_s", kind="mergesort")
    t = g["time_s"].to_numpy(dtype=float)
    y = g["temp_c"].to_numpy(dtype=float)
    total = 0.0
    for i in range(1, len(g)):
        t0, t1 = t[i - 1], t[i]
        y0, y1 = y[i - 1], y[i]
        if t1 <= t0:
            continue
        if y0 > thr and y1 > thr:
            total += (t1 - t0)
            continue
        crosses = (y0 <= thr < y1) or (y1 <= thr < y0)
        if crosses and (y1 != y0):
            frac = (thr - y0) / (y1 - y0)
            tcross = t0 + frac * (t1 - t0)
            if y0 <= thr and y1 > thr:
                total += (t1 - tcross)
            else:
                total += (tcross - t0)
    return float(total)


def safe_float(x: Any) -> Optional[float]:
    try:
        v = float(x)
    except Exception:
        return None
    if math.isnan(v) or math.isinf(v):
        return None
    return v


def compute_q01(cfg: HandbookCfg, runs: pd.DataFrame, tc: pd.DataFrame) -> Dict[str, Any]:
    by_run: Dict[str, Any] = {}
    violating: List[str] = []

    for run_id in sorted(runs["run_id"].astype(str).unique()):
        df_run = tc[tc["run_id"] == run_id]
        items: List[Tuple[str, float]] = []
        for tc_id, df_one in df_run.groupby("tc_id", sort=True):
            v = max_slope_in_temp_band(df_one, cfg.preheat_tmin_c, cfg.preheat_tmax_c)
            if v is not None:
                items.append((str(tc_id), float(v)))

        if not items:
            by_run[run_id] = {"tc_id": None, "max_preheat_ramp_c_per_s": None}
            continue

        # Representative per handbook intent: worst-case (maximum) rate of rise, tie by smallest tc_id.
        sel_tc, sel_val = sorted(items, key=lambda x: (-x[1], x[0]))[0]
        by_run[run_id] = {"tc_id": sel_tc, "max_preheat_ramp_c_per_s": r2(sel_val)}
        if sel_val > cfg.ramp_rate_limit_c_per_s:
            violating.append(run_id)

    return {
        "ramp_rate_limit_c_per_s": r2(cfg.ramp_rate_limit_c_per_s),
        "violating_runs": sorted(violating),
        "max_ramp_by_run": by_run,
    }


def compute_q02(cfg: HandbookCfg, runs: pd.DataFrame, tc: pd.DataFrame) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []

    liquidus_by_run = {
        str(r.run_id): safe_float(r.solder_liquidus_c) for r in runs.itertuples(index=False)
    }

    for run_id in sorted(runs["run_id"].astype(str).unique()):
        thr = liquidus_by_run.get(run_id)
        df_run = tc[tc["run_id"] == run_id]

        items: List[Tuple[str, float]] = []
        if thr is not None and not df_run.empty:
            for tc_id, df_one in df_run.groupby("tc_id", sort=True):
                tal = time_above_threshold_s(df_one, thr)
                items.append((str(tc_id), float(tal)))

        if not items or thr is None:
            out.append(
                {
                    "run_id": run_id,
                    "tc_id": None,
                    "tal_s": None,
                    "required_min_tal_s": r2(cfg.tal_min_s),
                    "required_max_tal_s": r2(cfg.tal_max_s),
                    "status": "non-compliant",
                }
            )
            continue

        # Mandatory representative sensor rule: minimum TAL across all TCs, tie by tc_id.
        sel_tc, sel_tal = sorted(items, key=lambda x: (x[1], x[0]))[0]
        status = (
            "compliant"
            if (cfg.tal_min_s <= sel_tal <= cfg.tal_max_s)
            else "non-compliant"
        )
        out.append(
            {
                "run_id": run_id,
                "tc_id": sel_tc,
                "tal_s": r2(sel_tal),
                "required_min_tal_s": r2(cfg.tal_min_s),
                "required_max_tal_s": r2(cfg.tal_max_s),
                "status": status,
            }
        )

    return out


def compute_q03(cfg: HandbookCfg, runs: pd.DataFrame, tc: pd.DataFrame) -> Dict[str, Any]:
    out_by_run: Dict[str, Any] = {}
    failing: List[str] = []

    liquidus_by_run = {
        str(r.run_id): safe_float(r.solder_liquidus_c) for r in runs.itertuples(index=False)
    }

    for run_id in sorted(runs["run_id"].astype(str).unique()):
        liquidus = liquidus_by_run.get(run_id)
        required = (liquidus + cfg.peak_margin_c) if liquidus is not None else None

        df_run = tc[tc["run_id"] == run_id]
        items: List[Tuple[str, float]] = []
        if not df_run.empty:
            for tc_id, df_one in df_run.groupby("tc_id", sort=True):
                peak = safe_float(df_one["temp_c"].max())
                if peak is not None:
                    items.append((str(tc_id), float(peak)))

        if not items:
            out_by_run[run_id] = {
                "tc_id": None,
                "peak_temp_c": None,
                "required_min_peak_c": r2(required),
            }
            failing.append(run_id)
            continue

        # Coldest sensor governs peak compliance: minimum peak across TCs, tie by tc_id.
        sel_tc, sel_peak = sorted(items, key=lambda x: (x[1], x[0]))[0]
        out_by_run[run_id] = {
            "tc_id": sel_tc,
            "peak_temp_c": r2(sel_peak),
            "required_min_peak_c": r2(required),
        }

        if required is None or sel_peak < required:
            failing.append(run_id)

    return {"failing_runs": sorted(failing), "min_peak_by_run": out_by_run}


def compute_q04(runs: pd.DataFrame) -> List[Dict[str, Any]]:
    # Handbook equation (as printed):
    # LINE SPEED = (BOARDS PER MINUTE) x (LENGTH PER BOARD (MINIMUM)) / (LOAD FACTOR)
    out: List[Dict[str, Any]] = []
    for r in runs.itertuples(index=False):
        run_id = str(r.run_id)
        bpm = safe_float(getattr(r, "boards_per_min", None))
        board_len = safe_float(getattr(r, "board_length_cm", None))
        load_factor = safe_float(getattr(r, "loading_factor", None))
        actual = safe_float(getattr(r, "conveyor_speed_cm_min", None))

        required = None
        if bpm is not None and board_len is not None and load_factor not in (None, 0.0):
            required = (bpm * board_len) / load_factor

        meets = False
        if required is not None and actual is not None:
            meets = actual >= required

        out.append(
            {
                "run_id": run_id,
                "required_min_speed_cm_min": r2(required),
                "actual_speed_cm_min": r2(actual),
                "meets": bool(meets),
            }
        )

    out.sort(key=lambda d: d["run_id"])
    return out


def compute_q05(
    runs: pd.DataFrame,
    defects: pd.DataFrame,
    q01: Dict[str, Any],
    q02: List[Dict[str, Any]],
    q03: Dict[str, Any],
    q04: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    runs = runs.copy()
    runs["run_id"] = runs["run_id"].astype(str)
    runs["board_family"] = runs["board_family"].astype(str)

    # Yield per run from SUMMARY rows.
    summ = defects[defects["inspection_stage"].astype(str) == "SUMMARY"].copy()
    summ["run_id"] = summ["run_id"].astype(str)

    def _sum_num(s: pd.Series) -> float:
        return float(pd.to_numeric(s, errors="coerce").fillna(0.0).sum())

    yield_by_run: Dict[str, Optional[float]] = {}
    if not summ.empty:
        g = summ.groupby("run_id", sort=False)
        for run_id, df in g:
            tested = _sum_num(df.get("units_tested"))
            passed = _sum_num(df.get("units_pass"))
            if tested > 0:
                yield_by_run[str(run_id)] = (passed / tested) * 100.0
            else:
                y = safe_float(df.get("fp_yield_pct").iloc[0] if "fp_yield_pct" in df.columns else None)
                yield_by_run[str(run_id)] = y

    # Total defect counts (excluding SUMMARY) for tie-breaks.
    nons = defects[defects["inspection_stage"].astype(str) != "SUMMARY"].copy()
    nons["run_id"] = nons["run_id"].astype(str)
    nons["count"] = pd.to_numeric(nons["count"], errors="coerce")
    defect_count_by_run = nons.groupby("run_id")["count"].sum(min_count=1).to_dict()

    ramp_limit = safe_float(q01.get("ramp_rate_limit_c_per_s"))
    ramp_by_run = q01.get("max_ramp_by_run", {})

    tal_status_by_run = {d["run_id"]: d["status"] for d in q02}
    peak_failing = set(q03.get("failing_runs", []))
    speed_by_run = {d["run_id"]: bool(d["meets"]) for d in q04}

    def is_compliant(run_id: str) -> bool:
        rb = ramp_by_run.get(run_id, {})
        rv = safe_float(rb.get("max_preheat_ramp_c_per_s"))
        ramp_ok = (rv is not None) and (ramp_limit is not None) and (rv <= ramp_limit)
        tal_ok = tal_status_by_run.get(run_id) == "compliant"
        peak_ok = run_id not in peak_failing
        speed_ok = speed_by_run.get(run_id, False)
        return bool(ramp_ok and tal_ok and peak_ok and speed_ok)

    records: List[Dict[str, Any]] = []

    for fam, df_fam in runs.groupby("board_family", sort=True):
        candidates = []
        for r in df_fam.itertuples(index=False):
            run_id = str(r.run_id)
            yld = yield_by_run.get(run_id)
            if yld is None:
                yld = float("-inf")
            defects_n = safe_float(defect_count_by_run.get(run_id))
            if defects_n is None:
                defects_n = float("inf")
            bpm = safe_float(getattr(r, "boards_per_min", None))
            if bpm is None:
                bpm = float("-inf")
            conv = safe_float(getattr(r, "conveyor_speed_cm_min", None))
            if conv is None:
                conv = float("-inf")

            candidates.append(
                (
                    1 if is_compliant(run_id) else 0,
                    yld,
                    -defects_n,
                    bpm,
                    conv,
                    -ord(run_id[0]),
                    run_id,
                )
            )

        # Sort: compliant first, then higher yield, then fewer defects, then higher throughput.
        candidates.sort(key=lambda t: (-t[0], -t[1], -t[2], -t[3], -t[4], t[6]))
        best_run_id = candidates[0][6]
        runner_up = sorted([str(r.run_id) for r in df_fam.itertuples(index=False) if str(r.run_id) != best_run_id])

        records.append(
            {
                "board_family": str(fam),
                "best_run_id": best_run_id,
                "runner_up_run_ids": runner_up,
            }
        )

    records.sort(key=lambda d: d["board_family"])
    return records


def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)

    runs = pd.read_csv(DATA_DIR / "mes_log.csv")
    tc = pd.read_csv(DATA_DIR / "thermocouples.csv")
    defects = pd.read_csv(DATA_DIR / "test_defects.csv")

    runs["run_id"] = runs["run_id"].astype(str)
    tc["run_id"] = tc["run_id"].astype(str)
    tc["tc_id"] = tc["tc_id"].astype(str)

    runs = runs.sort_values(["run_id"], kind="mergesort")
    tc = tc.sort_values(["run_id", "tc_id", "time_s"], kind="mergesort")

    handbook_text = extract_handbook_text(DATA_DIR / "handbook.pdf")
    cfg = parse_handbook_cfg(handbook_text)

    q01 = compute_q01(cfg, runs, tc)
    q02 = compute_q02(cfg, runs, tc)
    q03 = compute_q03(cfg, runs, tc)
    q04 = compute_q04(runs)
    q05 = compute_q05(runs, defects, q01, q02, q03, q04)

    (OUT_DIR / "q01.json").write_text(json.dumps(q01, indent=2, sort_keys=True), encoding="utf-8")
    (OUT_DIR / "q02.json").write_text(json.dumps(q02, indent=2), encoding="utf-8")
    (OUT_DIR / "q03.json").write_text(json.dumps(q03, indent=2, sort_keys=True), encoding="utf-8")
    (OUT_DIR / "q04.json").write_text(json.dumps(q04, indent=2), encoding="utf-8")
    (OUT_DIR / "q05.json").write_text(json.dumps(q05, indent=2), encoding="utf-8")

    # Required verification: parse all output JSON files.
    for i in range(1, 6):
        p = OUT_DIR / f"q0{i}.json"
        if not p.is_file() or p.stat().st_size == 0:
            raise RuntimeError(f"Missing output: {p}")
        json.loads(p.read_text(encoding="utf-8"))

    # Coverage checks
    run_ids = sorted(runs["run_id"].unique())
    assert set(q01["max_ramp_by_run"].keys()) == set(run_ids)
    assert [d["run_id"] for d in q02] == run_ids
    assert set(q03["min_peak_by_run"].keys()) == set(run_ids)
    assert [d["run_id"] for d in q04] == run_ids
    assert q05 and len(q05) == runs["board_family"].nunique()


if __name__ == "__main__":
    main()
"}

