def unescape_pdf_str(bs: bytes) -> str:
    bs=bs[1:-1]
    out=bytearray(); i=0
    while i < len(bs):
        c=bs[i]
        if c==0x5c and i+1 < len(bs):
            n=bs[i+1]
            if n in b'nrtbf':
                out.append({ord('n'):10,ord('r'):13,ord('t'):9,ord('b'):8,ord('f'):12}[n])
                i+=2; continue
            if 48<=n<=55:
